package app

const indexHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>s/watcher</title><style nonce="{{.CSPNonce}}">
.rbf-warning{display:inline-block;margin-top:6px;padding:3px 7px;border-radius:999px;background:#f2b84b;color:#18120a;font-family:system-ui,sans-serif;font-size:.7rem;font-weight:800;line-height:1.35}
.op-return{display:block;margin-top:7px;padding:5px 8px;border-radius:6px;background:#d8dadd;color:#111;font-family:system-ui,sans-serif;font-size:.76rem;line-height:1.35;white-space:pre-wrap;overflow-wrap:anywhere}.op-return-label{font-weight:800;margin-right:5px}
.metadata-tag{display:inline-block;padding:3px 9px!important;border:0!important;border-radius:999px;color:#17120a!important;font-size:.76rem!important;font-weight:700;line-height:1.35;margin-bottom:6px;letter-spacing:normal;text-transform:none}
[hidden]{display:none!important}
:root{color-scheme:dark;--bg:#0b0d10;--card:#151920;--ink:#f4f1ea;--muted:#9da5b2;--gold:#f2a900;--line:#29303a;--bad:#ff746c;--good:#72d69b;--idle:#657080}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}.wrap{width:min(1120px,94vw);margin:48px auto}.top,.section-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.controls{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.controls button{background:transparent;color:var(--muted);border-color:var(--line)}h1{font-size:2.4rem;margin:0}.tag{color:var(--gold);letter-spacing:.08em;text-transform:uppercase;font-size:.78rem}.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin-top:22px}.identity{display:flex;gap:16px;align-items:center}.identity img{width:84px;height:84px;border-radius:14px;background:#0e1116;border:1px solid var(--line)}form.add{display:grid;grid-template-columns:1fr 1fr 2fr 150px auto;gap:10px}.options{grid-column:1/-1;display:flex;gap:20px;align-items:center;color:var(--muted);font-size:.85rem}.options label{display:flex;gap:7px;align-items:center}.options input{width:76px}.options input[type=checkbox]{width:auto}input,select,button{border:1px solid var(--line);border-radius:8px;padding:11px 13px;background:#0e1116;color:var(--ink)}button{background:var(--gold);border-color:var(--gold);color:#17120a;font-weight:700;cursor:pointer}button:disabled{opacity:.45;cursor:default}.row-actions{display:grid;gap:6px;min-width:78px}.row-actions button{width:100%;padding:7px 9px;background:transparent;color:var(--muted);border-color:var(--line)}.row-actions .remove button{color:var(--bad)}.edit-form{display:grid;grid-template-columns:1fr 1fr auto;gap:6px;margin-top:10px}.edit-form input,.edit-form button{padding:7px 9px;min-width:0}.sort-form{display:flex;gap:8px;align-items:center;color:var(--muted)}.sort-form select{padding:7px 9px}.category{display:inline-block;padding:2px 8px;border:1px solid #5e4b18;border-radius:999px;color:var(--gold);font-size:.72rem;margin-bottom:5px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px 8px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);font-size:.75rem;text-transform:uppercase}.watch-row.signal-idle>td:first-child{box-shadow:inset 4px 0 var(--idle);padding-left:14px}.watch-row.signal-received>td:first-child{box-shadow:inset 4px 0 var(--good);padding-left:14px}.watch-row.signal-sent>td:first-child{box-shadow:inset 4px 0 var(--bad);padding-left:14px}.address,.tx{font-family:ui-monospace,monospace;font-size:.78rem;word-break:break-all;color:var(--muted)}.masked{font-family:"Noto Sans Symbols 2","Segoe UI Symbol",ui-monospace,monospace;letter-spacing:.12em}.error,.sent{color:var(--bad)}.received{color:var(--good)}.kind{text-transform:capitalize}.empty{color:var(--muted);padding:20px 0}dialog{width:min(480px,90vw);border:1px solid var(--line);border-radius:14px;padding:24px;background:var(--card);color:var(--ink);box-shadow:0 24px 80px #000b}dialog::backdrop{background:#000a}dialog h2{margin-top:0}dialog p{color:var(--muted)}dialog form{display:flex;justify-content:flex-end;margin-top:22px}@media(max-width:700px){.top,.section-head{display:block}.controls{justify-content:flex-start;margin-top:16px}.sort-form{margin-top:12px}form.add,.edit-form{grid-template-columns:1fr}.options{align-items:flex-start;flex-direction:column;gap:8px}table,thead,tbody,tr,th,td{display:block}thead{display:none}tr{padding:12px 0;border-bottom:1px solid var(--line)}td{border:0;padding:4px 0}.row-actions{display:flex;margin-top:8px}}
</style></head><body><main class="wrap"><header class="top"><div><div class="tag">Satoshi's watcher</div><h1>s/watcher</h1><p>Local, watch-only Bitcoin activity monitoring with notifications.</p></div><div class="controls"><form method="post" action="/logout"><button>Sign out</button></form></div></header>
{{if .Nostr}}<section class="card identity"><img src="{{.Nostr.Avatar}}" alt="Pixelbot avatar"><div><div class="tag">Nostr notification sender</div><h2>{{.Nostr.Name}}</h2><div class="address">{{.Nostr.Npub}}</div></div></section>{{end}}
<datalist id="group-suggestions">{{range .GroupSuggestions}}<option value="{{.}}">{{end}}</datalist><section class="card"><form class="add" method="post" action="/watches"><input name="label" maxlength="80" pattern="[A-Za-z0-9_ ]+" title="Letters, numbers, spaces, and underscores; uppercase is saved as lowercase" required placeholder="name, e.g. websitebtc"><input name="category" maxlength="60" pattern="[A-Za-z0-9_ ]+" title="Letters, numbers, spaces, and underscores; uppercase is saved as lowercase" list="group-suggestions" placeholder="group, e.g. donations"><input name="source" required autocomplete="off" placeholder="Bitcoin address, xpub/ypub/zpub, or descriptor"><select name="script_type" aria-label="Address type" hidden><option value="">Choose xpub address type</option><option value="native-segwit">Native SegWit</option><option value="nested-segwit">Nested SegWit</option><option value="legacy">Legacy</option><option value="taproot">Taproot</option></select><button>Add watch</button><div class="options" hidden><label><input name="include_change" type="checkbox" checked> Include /1 change branch</label><span>Smart discovery derives addresses automatically using the gap configured in StartOS Actions. Descriptors, ypubs, and zpubs determine their address type automatically.</span></div></form></section>
<section class="card"><div class="section-head"><h2>Watched wallets and addresses</h2><form class="sort-form" method="get"><label for="sort">Sort by</label><select id="sort" name="sort"><option value="balance" {{if eq .SortMode "balance"}}selected{{end}}>Stack size</option><option value="name" {{if eq .SortMode "name"}}selected{{end}}>Name</option><option value="group" {{if eq .SortMode "group"}}selected{{end}}>Group</option><option value="date" {{if eq .SortMode "date"}}selected{{end}}>Date added</option><option value="activity" {{if eq .SortMode "activity"}}selected{{end}}>Latest change</option><option value="type" {{if eq .SortMode "type"}}selected{{end}}>Type</option></select></form></div>{{if .Groups}}<table><thead><tr><th>Name and group</th><th>Coverage</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>{{range .Groups}}<tr class="watch-row signal-{{.ActivitySignal}}"><td><div id="view-{{.ID}}"><span class="category">{{.Category}}</span><br><strong>{{.Label}}</strong><div class="address">{{.DisplaySource}}</div></div><form class="edit-form" id="edit-{{.ID}}" method="post" action="/groups/{{.ID}}/update" hidden><input name="label" maxlength="80" pattern="[A-Za-z0-9_ ]+" title="Letters, numbers, spaces, and underscores; uppercase is saved as lowercase" required value="{{.Label}}" aria-label="Watch name"><input name="category" maxlength="60" pattern="[A-Za-z0-9_ ]+" title="Letters, numbers, spaces, and underscores; uppercase is saved as lowercase" list="group-suggestions" required value="{{.Category}}" aria-label="Watch group"><button>Save</button></form></td><td>{{.Addresses}} addresses<div class="address">{{.ScriptType}}{{if .IncludeChange}} · receive + change{{end}}</div></td><td class="{{if $.PrivacyMode}}masked{{end}}">{{.DisplayBalance}}</td><td>{{if .LastError}}<span class="error">{{.LastError}}</span>{{else if eq .Ready .Addresses}}Checked {{.LastChecked.Format "2006-01-02 15:04 UTC"}}{{else}}{{.Ready}} / {{.Addresses}} initialized{{end}}</td><td><div class="row-actions"><form class="remove" method="post" action="/groups/{{.ID}}/delete"><button>Remove</button></form><button type="button" class="edit-toggle" data-id="{{.ID}}">Edit</button><button type="button" class="edit-cancel" data-id="{{.ID}}" hidden>Cancel</button></div></td></tr>{{end}}</tbody></table>{{else}}<div class="empty">No addresses, extended keys, or descriptors are being watched yet.</div>{{end}}</section>
<section class="card"><h2>New activity</h2>{{if .Events}}<table><thead><tr><th>Watch</th><th>Activity</th><th>Amount</th><th>Transaction</th><th>State</th><th>Detected</th></tr></thead><tbody>{{range .Events}}<tr><td>{{if .GroupID}}{{watchLabel .GroupID}}{{else}}{{watchLabel .WatchID}}{{end}}</td><td class="kind {{.Direction}}">{{.Direction}}</td><td class="{{if $.PrivacyMode}}masked{{end}}">{{.DisplayAmount}}</td><td class="tx">{{.DisplayTxID}}{{range .OPReturn}}<span class="op-return"><span class="op-return-label">OP_RETURN</span>{{.}}</span>{{end}}</td><td>{{if gt .Height 0}}Block {{.Height}}{{else}}Mempool{{if and .Replaceable (eq .Direction "received")}}<br><span class="rbf-warning">Replaceable — do not treat as final until confirmed.</span>{{end}}{{end}}</td><td>{{.SeenAt.Format "2006-01-02 15:04 UTC"}}</td></tr>{{end}}</tbody></table>{{else}}<div class="empty">No new activity detected after the initial scans.</div>{{end}}</section>
</main><footer class="legal" style="width:min(1120px,94vw);margin:0 auto 40px;color:#9da5b2;font-size:.78rem;text-align:center">Copyleft software by <a href="https://njump.me/npub1qqqqqqz7nhdqz3uuwmzlflxt46lyu7zkuqhcapddhgz66c4ddynswreecw" target="_blank" rel="noopener noreferrer" style="color:inherit">StellarStoic</a>. Licensed under the <a href="https://github.com/StellarStoic/swatcher/blob/main/LICENSE" target="_blank" rel="noopener noreferrer" style="color:inherit">GNU AGPL v3 or later</a>, without warranty. <a href="https://github.com/StellarStoic/swatcher" target="_blank" rel="noopener noreferrer" style="color:inherit">Corresponding source code</a>.</footer><dialog id="watch-error"><h2></h2><p></p><form method="dialog"><button>Close</button></form></dialog><script nonce="{{.CSPNonce}}">
const addForm=document.querySelector('form.add'),source=addForm.elements.source,type=addForm.elements.script_type,options=addForm.querySelector('.options'),errorDialog=document.querySelector('#watch-error');
function showFormError(title,message){errorDialog.querySelector('h2').textContent=title;errorDialog.querySelector('p').textContent=message;errorDialog.showModal()}
function tagColor(value){const key=value.trim().toLocaleLowerCase().replace(/\s+/g,' ');let hash=2166136261;for(const character of key){hash^=character.codePointAt(0);hash=Math.imul(hash,16777619)}return 'hsl('+(hash>>>0)%360+' 72% 78%)'}
document.querySelectorAll('.category').forEach(groupTag=>{const nameTag=groupTag.parentElement.querySelector('strong');for(const tag of [groupTag,nameTag]){if(!tag)continue;tag.classList.add('metadata-tag');tag.style.backgroundColor=tagColor(tag.textContent)}});
function updateSourceFields(){const value=source.value.trim(),plainXpub=value.startsWith('xpub')&&!value.includes('('),derivable=/^(xpub|ypub|zpub)/.test(value)||value.includes('(');type.hidden=!plainXpub;type.required=plainXpub;if(!plainXpub)type.value='';options.hidden=!derivable}
source.addEventListener('input',updateSourceFields);updateSourceFields();
addForm.addEventListener('submit',async event=>{event.preventDefault();const button=addForm.querySelector('button[type="submit"],button:not([type])');button.disabled=true;try{const response=await fetch(addForm.action,{method:'POST',headers:{Accept:'application/json'},body:new FormData(addForm)});const body=await response.json().catch(()=>({}));if(response.ok){if(body.id)sessionStorage.setItem('focus-watch',body.id);location.reload();return}showFormError('Could not add watch',body.error||'The watch could not be added.')}catch(_){showFormError('Could not add watch','s/watcher could not process the request. Please try again.')}finally{button.disabled=false}});
document.querySelectorAll('.edit-toggle').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.id;document.querySelector('#view-'+id).hidden=true;document.querySelector('#edit-'+id).hidden=false;button.disabled=true;document.querySelector('.edit-cancel[data-id="'+id+'"]').hidden=false}));
document.querySelectorAll('.edit-cancel').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.id,form=document.querySelector('#edit-'+id),edit=document.querySelector('.edit-toggle[data-id="'+id+'"]');form.reset();form.hidden=true;document.querySelector('#view-'+id).hidden=false;edit.disabled=false;button.hidden=true}));
document.querySelectorAll('.edit-form').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const response=await fetch(form.action,{method:'POST',headers:{Accept:'application/json'},body:new FormData(form)});if(response.ok){location.reload();return}const body=await response.json().catch(()=>({error:'The changes could not be saved.'}));showFormError('Could not update watch',body.error||'The changes could not be saved.')}catch(_){showFormError('Could not update watch','s/watcher could not process the request. Please try again.')}finally{button.disabled=false}}));
const sortSelect=document.querySelector('#sort');sortSelect.removeAttribute('onchange');sortSelect.addEventListener('change',()=>{sessionStorage.setItem('focus-watches','1');sortSelect.form.submit()});const addedWatch=sessionStorage.getItem('focus-watch');if(addedWatch){sessionStorage.removeItem('focus-watch');document.getElementById('view-'+addedWatch)?.closest('.watch-row')?.scrollIntoView({block:'center'})}else if(sessionStorage.getItem('focus-watches')==='1'){sessionStorage.removeItem('focus-watches');document.querySelector('.watch-row')?.scrollIntoView({block:'start'})}
</script></body></html>`

const loginHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in · s/watcher</title><style nonce="{{.CSPNonce}}">:root{color-scheme:dark;--bg:#0b0d10;--card:#151920;--ink:#f4f1ea;--muted:#9da5b2;--gold:#f2a900;--line:#29303a;--bad:#ff746c}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}.login{width:min(420px,92vw);padding:28px;background:var(--card);border:1px solid var(--line);border-radius:16px}.tag{color:var(--gold);letter-spacing:.08em;text-transform:uppercase;font-size:.78rem}h1{margin:.2em 0}p{color:var(--muted)}form{display:grid;gap:12px;margin-top:24px}input,button{width:100%;border:1px solid var(--line);border-radius:8px;padding:12px 14px;background:#0e1116;color:var(--ink)}button{background:var(--gold);border-color:var(--gold);color:#17120a;font-weight:700;cursor:pointer}.forgot{margin-top:12px;background:transparent;border-color:transparent;color:var(--muted)}.error{color:var(--bad)}dialog{width:min(440px,90vw);padding:26px;border:1px solid var(--line);border-radius:14px;background:var(--card);color:var(--ink);box-shadow:0 24px 80px #000b}dialog::backdrop{background:#000a}dialog h2{margin-top:0}dialog form{display:flex;justify-content:flex-end;margin-top:22px}dialog form button{width:auto}</style></head><body><main class="login"><div class="tag">Satoshi's watcher</div><h1>s/watcher</h1>{{if .Configured}}{{if .Error}}<p class="error">Incorrect password.</p>{{else}}<p>Enter your web password to continue.</p>{{end}}<form method="post" action="/login"><input name="password" type="password" minlength="5" maxlength="256" required autofocus autocomplete="current-password" placeholder="Web password"><button>Sign in</button></form><button class="forgot" type="button" id="forgot-password">Forgot password?</button>{{else}}<p>The Web Interface is locked. Open the s/watcher service actions in StartOS and run <strong>Set Web Password</strong> first.</p>{{end}}</main>{{if .Configured}}<dialog id="recovery"><h2>Reset your web password</h2><p>Open <strong>s/watcher</strong> in StartOS, select <strong>Actions</strong>, and run <strong>Set Web Password</strong>. Enter and confirm a new password there.</p><p>Saving it replaces the password and signs out every existing browser session. Your watches and notification settings are not changed.</p><form method="dialog"><button>Close</button></form></dialog><script nonce="{{.CSPNonce}}">const recovery=document.querySelector('#recovery');document.querySelector('#forgot-password').addEventListener('click',()=>recovery.showModal())</script>{{end}}</body></html>`
